import{_ as t,o,c as r,ag as a}from"./chunks/framework.DXGyWiRo.js";const m=JSON.parse('{"title":"Architecture Skill","description":"","frontmatter":{},"headers":[],"relativePath":"skills/architecture.md","filePath":"skills/architecture.md"}'),s={name:"skills/architecture.md"};function i(c,e,n,d,l,u){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="architecture-skill" tabindex="-1">Architecture Skill <a class="header-anchor" href="#architecture-skill" aria-label="Permalink to &quot;Architecture Skill&quot;">​</a></h1><p>The Architecture Skill provides architectural guidance, modernization recommendations, and Well-Architected Framework assessments for Azure resources.</p><h2 id="capability" tabindex="-1">Capability <a class="header-anchor" href="#capability" aria-label="Permalink to &quot;Capability&quot;">​</a></h2><ul><li>Analyzes current resource architecture via Azure Resource Graph</li><li>Retrieves Advisor recommendations across all pillars</li><li>Provides modernization and best-practice guidance aligned with the Azure Well-Architected Framework</li></ul><h2 id="skill-configuration" tabindex="-1">Skill Configuration <a class="header-anchor" href="#skill-configuration" aria-label="Permalink to &quot;Skill Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Skill Name</td><td><code>ArchitectureSkill</code></td></tr><tr><td>Model</td><td><code>gpt-4o</code></td></tr><tr><td>Temperature</td><td><code>0.0</code></td></tr><tr><td>Timeout</td><td><code>120s</code></td></tr></tbody></table><h2 id="system-prompt-summary" tabindex="-1">System Prompt Summary <a class="header-anchor" href="#system-prompt-summary" aria-label="Permalink to &quot;System Prompt Summary&quot;">​</a></h2><p>The LLM acts as an Azure Solutions Architect with expertise across all Well-Architected Framework pillars:</p><ul><li><strong>Reliability</strong> — redundancy, failover, disaster recovery</li><li><strong>Security</strong> — identity, network security, data protection</li><li><strong>Cost Optimization</strong> — right-sizing, reserved instances, waste elimination</li><li><strong>Operational Excellence</strong> — monitoring, automation, incident response</li><li><strong>Performance Efficiency</strong> — scaling, caching, latency optimization</li></ul><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>ResourceGraphTools-QueryResources</code></td><td><code>QueryResources(subscriptionIds, resourceType?)</code></td><td>Lists resources with type, location, SKU, and tags (up to 50)</td></tr><tr><td><code>ResourceGraphTools-GetResourceDetails</code></td><td><code>GetResourceDetails(resourceId)</code></td><td>Full resource details including properties, identity, and kind</td></tr><tr><td><code>AdvisorRecommendationTools-GetRecommendations</code></td><td><code>GetRecommendations(subscriptionIds, category?)</code></td><td>Queries Advisor across any category (up to 20 recommendations)</td></tr><tr><td><code>AdvisorRecommendationTools-GetRecommendationDetails</code></td><td><code>GetRecommendationDetails(recommendationId)</code></td><td>Full details for a specific recommendation</td></tr><tr><td><code>SubscriptionTools-ListResourceGroups</code></td><td><code>ListResourceGroups(subscriptionId)</code></td><td>Lists resource groups for scoping</td></tr></tbody></table><h2 id="data-sources" tabindex="-1">Data Sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data Sources&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Azure Resource Graph</span></span>
<span class="line"><span>    └─ Resources | project id, name, type, resourceGroup, location, sku, tags</span></span>
<span class="line"><span>    └─ Full resource properties via GetResourceDetails</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Azure Advisor</span></span>
<span class="line"><span>    └─ All recommendation categories</span></span>
<span class="line"><span>    └─ advisorresources | type == &quot;microsoft.advisor/recommendations&quot;</span></span></code></pre></div><h2 id="example-queries" tabindex="-1">Example Queries <a class="header-anchor" href="#example-queries" aria-label="Permalink to &quot;Example Queries&quot;">​</a></h2><blockquote><p>&quot;Review the architecture of my production environment and suggest improvements&quot;</p></blockquote><p><strong>Tool Calls:</strong></p><ol><li><code>ResourceGraphTools-QueryResources([&quot;sub-prod&quot;])</code> → resource inventory</li><li><code>AdvisorRecommendationTools-GetRecommendations([&quot;sub-prod&quot;])</code> → all-category recommendations</li><li><code>ResourceGraphTools-GetResourceDetails(resourceId)</code> → deep-dive on key resources</li></ol><blockquote><p>&quot;Should I modernize my VM-based workloads to containers?&quot;</p></blockquote><p><strong>Tool Calls:</strong></p><ol><li><code>ResourceGraphTools-QueryResources([&quot;sub-prod&quot;], &quot;Microsoft.Compute/virtualMachines&quot;)</code> → VM inventory</li><li><code>AdvisorRecommendationTools-GetRecommendations([&quot;sub-prod&quot;])</code> → modernization recommendations</li></ol>`,20)])])}const h=t(s,[["render",i]]);export{m as __pageData,h as default};
